create or replace function public.get_my_property_installments(_order_id uuid) returns table(id uuid,installment_number integer,scheduled_amount numeric,amount_paid numeric,balance numeric,status text,due_date timestamptz) language sql security definer set search_path=public as $$ select i.id,i.installment_number,coalesce(i.amount_due,0) as scheduled_amount,coalesce(i.amount_paid,0),greatest(coalesce(i.amount_due,0)-coalesce(i.amount_paid,0),0) as balance,i.status,i.due_date from public.order_installments i join public.orders o on o.id=i.order_id where i.order_id=_order_id and o.user_id=auth.uid() order by i.installment_number $$; grant execute on function public.get_my_property_installments(uuid) to authenticated;
